#include "dse/storage/posting_codec.hpp"
#include <limits>
namespace dse::storage {namespace {CodecError fail(CodecErrorCode code,std::string message){return {code,std::move(message)};}}
void VariableByteCodec::encode(std::uint32_t value,std::vector<std::byte>& output){do{std::uint8_t byte=static_cast<std::uint8_t>(value&0x7fU);value>>=7U;if(value==0U)byte|=0x80U;output.push_back(static_cast<std::byte>(byte));}while(value!=0U);}
std::expected<std::uint32_t,CodecError> VariableByteCodec::decode(std::span<const std::byte> input,std::size_t& offset){std::uint32_t value{};for(unsigned shift=0;shift<=28U;shift+=7U){if(offset==input.size())return std::unexpected(fail(CodecErrorCode::truncated,"truncated variable-byte integer"));const auto byte=std::to_integer<std::uint8_t>(input[offset++]);const auto payload=static_cast<std::uint32_t>(byte&0x7fU);if(shift==28U&&payload>15U)return std::unexpected(fail(CodecErrorCode::overflow,"variable-byte integer overflow"));value|=payload<<shift;if((byte&0x80U)!=0U){if(shift!=0U&&payload==0U)return std::unexpected(fail(CodecErrorCode::non_canonical,"non-canonical variable-byte integer"));return value;}}return std::unexpected(fail(CodecErrorCode::overflow,"variable-byte integer is too long"));}
std::expected<std::vector<std::byte>,CodecError> VariableByteCodec::encode_deltas(std::span<const std::uint32_t> sorted){std::vector<std::byte> output;std::uint32_t previous{};for(const auto value:sorted){if(value<=previous)return std::unexpected(fail(CodecErrorCode::invalid_order,"values are not strictly increasing"));encode(value-previous,output);previous=value;}return output;}
std::expected<std::vector<std::uint32_t>,CodecError> VariableByteCodec::decode_deltas(std::span<const std::byte> input,std::size_t expected_count,std::size_t maximum_count){if(expected_count>maximum_count)return std::unexpected(fail(CodecErrorCode::resource_limit,"decoded integer count exceeds limit"));std::vector<std::uint32_t> result;result.reserve(expected_count);std::size_t offset{};std::uint32_t previous{};for(std::size_t i=0;i<expected_count;++i){auto delta=decode(input,offset);if(!delta)return std::unexpected(delta.error());if(*delta==0U||*delta>std::numeric_limits<std::uint32_t>::max()-previous)return std::unexpected(fail(CodecErrorCode::invalid_order,"delta sequence is not strictly increasing"));previous+=*delta;result.push_back(previous);}if(offset!=input.size())return std::unexpected(fail(CodecErrorCode::non_canonical,"trailing variable-byte data"));return result;}
}  // namespace dse::storage
